REVOKE ALL ON FUNCTION public.handle_new_user() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.set_updated_at() FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public.has_role(uuid, public.app_role) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.has_role(uuid, public.app_role) TO authenticated;

INSERT INTO public.products (slug, name, brand, category_slug, description, price, original_price, rating, review_count, stock, sku, specifications, tags, featured, seller, delivery_days)
SELECT
  trim(both '-' from regexp_replace(lower(t.name), '[^a-z0-9]+', '-', 'g')),
  t.name, t.brand, t.cat, t.descr, t.price, t.mrp, t.rating, t.reviews, t.stock,
  'AM-' || upper(substr(t.cat,1,3)) || '-' || (1000 + t.i),
  jsonb_build_object('Brand', t.brand, 'Model', trim(split_part(t.name,'(',1)), 'Warranty', '1 Year Manufacturer Warranty', 'Country of Origin', 'India', 'In the box', 'Product unit, user manual, warranty card'),
  ARRAY[t.cat, lower(t.brand), CASE WHEN t.mrp - t.price > 3000 THEN 'big-saving' ELSE 'value' END],
  (t.i % 7 = 0), t.brand || ' Official Store', 2 + (t.i % 4)
